codeExample.code:
create table public.learning_notes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id),
  body text not null check (char_length(body) between 1 and 2000)
);
alter table public.learning_notes enable row level security;
revoke all on public.learning_notes from anon, authenticated;
grant select, insert on public.learning_notes to authenticated;
create policy read_own_notes on public.learning_notes
  for select to authenticated using ((select auth.uid()) = user_id);
create policy insert_own_notes on public.learning_notes
  for insert to authenticated with check ((select auth.uid()) = user_id);
